mapper.select:
SELECT id, task_id, thread_id, parent_task_id, ds_id, metric_name, kb_metric_id,
       metric_definition_verified, trigger_type, question, compare_type, status, review_state,
       anomaly_json, drill_depth, query_count, confidence, conclusion_summary,
       result_status, sensitive_flag, error_msg, create_time, update_time
FROM rcagent_attribution_task

    is_deleted = 0


            AND ds_id = #{q.dsId}


            AND metric_name LIKE CONCAT('%', #{q.metricName}, '%')


            AND trigger_type = #{q.triggerType}


            AND status = #{q.status}


            AND result_status = #{q.resultStatus}


            AND DATE(create_time) >= #{q.startDate}


            AND DATE(create_time) <= #{q.endDate}



ORDER BY create_time DESC, id DESC

SELECT id, task_id, thread_id, parent_task_id, ds_id, metric_name, kb_metric_id, metric_definition_verified, trigger_type, question, compare_type, status, review_state, anomaly_json, drill_depth, query_count, confidence, conclusion_summary, result_status, sensitive_flag, error_msg, create_time, update_time FROM rcagent_attribution_task WHERE is_deleted = 0 AND status = 'CONCLUSION_REVIEWING' AND review_state = 'CONCLUSION_REVIEWING'
AND ds_id = #{dsId}
AND task_id = #{taskId}
ORDER BY create_time DESC, id DESC
